/// 計測（N-1001）：同じ色のドーナツ形（穴のある面）が n 個の地図で、全部の確かめ（`valid_faces`）とバケツ
/// （`with_face_filled`）の時間。点を含む外周を探すのが面の数の2乗で増えないか
#[test]
#[ignore]
fn measure_many_holes() {
    use crate::planar_map::PlanarMap;
    use std::time::Instant;
    let red = Color32::from_rgb(235, 75, 75);
    for n in [500usize, 1000, 2000, 4000] {
        let side = (n as f64).sqrt().ceil() as usize;
        let shapes: Vec<FillShape> = (0..n)
            .map(|i| {
                let (x, y) = ((i % side) as f64 * 30.0, (i / side) as f64 * 30.0);
                let outer = map_overlay::rect_shape(x, y, x + 20.0, y + 20.0, red);
                let inner = map_overlay::rect_shape(x + 5.0, y + 5.0, x + 15.0, y + 15.0, red);
                let ext = outer.contours().next().unwrap().clone();
                // 穴は外周と逆の向き
                let hole = crate::vector_engine::Contour::new(
                    inner
                        .contours()
                        .next()
                        .unwrap()
                        .segments
                        .iter()
                        .rev()
                        .map(|q| QuadBez::new(q.p2, q.p1, q.p0))
                        .collect(),
                );
                FillShape::new(red, ext, vec![hole])
            })
            .collect();
        let m = PlanarMap::from_faces(shapes.iter());
        let t = Instant::now();
        let faces = m.valid_faces().expect("正しい地図");
        let check = t.elapsed().as_secs_f64() * 1e3;
        assert_eq!(faces.len(), n);
        let t = Instant::now();
        // 真ん中のドーナツの穴の中（色の無い所）を青で塗る
        let c = side / 2;
        let p = Point::new(c as f64 * 30.0 + 10.0, c as f64 * 30.0 + 10.0);
        let filled = m.with_face_filled(p, Color32::BLUE).is_some();
        let bucket = t.elapsed().as_secs_f64() * 1e3;
        eprintln!("n {n}: valid_faces {check:.1}ms, bucket {bucket:.1}ms (filled {filled})");
    }
}

/// ★1（レビュー「軽量化・高速化」）：ロック中のレイヤーを描き直すとき、セル画が変わらなければ、しまう地図から計算に
/// 使う写しを作り直さない（セル画の結合メッシュの写しを持つ：`CelMeshCache`）。再生中も同じ
#[test]
fn redrawing_a_locked_layer_does_not_rebuild_its_map() {
    let mut app = Is2dApp::default();
    put_cel_shapes(
        &mut app,
        0,
        0,
        make_stroke(
            Point::new(100.0, 100.0),
            Point::new(300.0, 160.0),
            10.0,
            Color32::from_rgb(220, 60, 60),
        ),
    );
    app.tab_mut().doc.root.layers[0].locked = true;
    app.tab_mut().refresh_scene_base();
    let ctx = egui::Context::default();
    let raw_input = egui::RawInput {
        screen_rect: Some(egui::Rect::from_min_size(
            egui::Pos2::ZERO,
            egui::vec2(1280.0, 820.0),
        )),
        ..Default::default()
    };
    let _ = ctx.run(raw_input.clone(), |ctx| app.update_ui(ctx));
    let before = crate::planar_map::dense_builds();
    for _ in 0..3 {
        let _ = ctx.run(raw_input.clone(), |ctx| app.update_ui(ctx));
    }
    assert_eq!(crate::planar_map::dense_builds(), before);
}

/// 矩形で一部を選ぶとき、中（片）と外（残り）を1回の重ね合わせで作る：入れる辺を決める・切る・面の色を伝えるのは1回
/// （`overlay_rules`。設計：claude/N-2002の残り・R5・★4・★5の設計_80fe785.md。直す前は中と外で別々に重ね合わせた）
#[test]
fn marquee_cut_overlays_once_for_inside_and_rest() {
    let mut app = Is2dApp::default();
    let lid = app.doc.root.layers[0].id;
    let mut stroke = make_stroke(
        Point::new(100.0, 100.0),
        Point::new(300.0, 100.0),
        20.0,
        Color32::RED,
    );
    stroke[0].layer_id = lid;
    put_cel_shapes(&mut app, 0, 0, stroke);
    let before = crate::planar_map::fed_runs();
    run(
        &mut app,
        &[Action::SelectMarquee {
            p0: Point::new(80.0, 70.0),
            p1: Point::new(200.0, 130.0),
            additive: false,
        }],
    );
    assert_eq!(crate::planar_map::fed_runs() - before, 1);
    let fl = app.session.floating().expect("片が浮く");
    assert_eq!(fl.pieces().len(), 1);
    assert_eq!(fl.remainder().count(), 1);
}

/// 重ね合わせの1回で、判定の形の索引を作るのは1回：曲線に戻す所（`ChainRestorer`）が作った索引を、続く
/// `merge_degree2` もそのまま使う（設計：claude/N-2002の残り・R5・★4・★5の設計_80fe785.md。直す前は2回）
#[test]
fn overlay_builds_the_shape_index_once() {
    use crate::planar_map::{MapInput, MapRule, PlanarMap};
    let red = Color32::from_rgb(235, 75, 75);
    let left = vec![map_overlay::rect_shape(0.0, 0.0, 100.0, 100.0, red)];
    let right = vec![map_overlay::rect_shape(50.0, 0.0, 150.0, 100.0, red)];
    let m = PlanarMap::default()
        .overlay(MapInput::Shapes(&left), MapRule::Paint(Some(red)))
        .unwrap();
    let before = crate::planar_map::index_builds();
    let m = m
        .overlay(MapInput::Shapes(&right), MapRule::Paint(Some(red)))
        .unwrap();
    assert_eq!(crate::planar_map::index_builds() - before, 1);
    // 重なった所の境目は消え、その端の切れ目もまとまって、1つの四角になる
    assert!(m.is_valid());
    assert_eq!((m.nodes.len(), m.edges.len()), (4, 4));
}
